insert into public.ls_items (code, grp, title, descr, unit, sort, div_code) values
 ('LS-41', $q$مركز نموذج المسار الرابع$q$, $q$تجهيز الموقع والسياج ولوحة المشروع$q$, $q$تنظيف الموقع العام وتسويته وإزالة النباتات والأنقاض والأكوام والطرق المؤقتة وتجهيزه لبدء العمل، وتوفير حاوية مخلفات بناء طوال مدة التنفيذ ونقل المخلفات وفق تعليمات البلدية؛ وتوريد وتركيب سياج مؤقت حول الموقع: الواجهة المطلة على الشارع الرئيسي بارتفاع 2.40 م من ألواح بلاي وود مع بانر مطبوع بجودة عالية بطولها حسب التصميم المعتمد، وباقي الحدود بارتفاع 1.80 م من ألواح شينكو مضلعة مدهونة أو مجلفنة، جميعها على شاسيه معدني مثبت بأنكرات أو قواعد خرسانية مصممة لأحمال الرياح؛ وتوريد وتركيب لوحة المشروع الخارجية بارتفاع كلي 5.00 م وعرض 2.50 م على شاسيه معدني بقواعد خرسانية: جزء علوي 2.50×2.50 م بصورة منظور المشروع واسمه، وأربع لوحات سفلية 0.50×2.50 م لاسم المتبرع والمقاول والاستشاري وتجمع الأحساء الصحي، من الألمنيوم أو الصاج المدهون بطباعة عالية الجودة، تُعتمد تصاميمها قبل التنفيذ؛ وإزالة السياج واللوحات المؤقتة عند التسليم. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 410, null),
 ('LS-42', $q$مركز نموذج المسار الرابع$q$, $q$المكاتب والمرافق المؤقتة والكهرباء والإنارة المؤقتة$q$, $q$توريد وتجهيز مكاتب متنقلة (بورتابل) طوال مدة التنفيذ بحد أدنى: مكتب للمقاول، ومكتب لفريق إدارة المشاريع والاستشاري بمساحة لا تقل عن 3×4 م، كل منهما مؤثث ومكيف ومزود بالإنترنت وشاشة لا تقل عن 50 بوصة؛ ودورتا مياه على الأقل مجهزتان بالمغاسل والصرف المناسب؛ ومواقع مناسبة لتخزين المواد وحمايتها؛ والمحافظة على نظافة المكاتب ودورات المياه وتوفر التكييف والمياه يومياً، وتأمين مياه الشرب والغلاية والثلاجة ومستلزمات الضيافة؛ وتأمين الكهرباء المؤقتة للموقع وتحمّل تكاليفها، والإنارة الكافية للعمل المسائي أو في شهر رمضان عند الحاجة؛ وإزالة كل ذلك وإعادة الموقع عند الانتهاء. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 420, null),
 ('LS-43', $q$مركز نموذج المسار الرابع$q$, $q$الدراسات والحسابات الهندسية والاختبارات المعملية$q$, $q$إعداد وتقديم الدراسات والحسابات الهندسية الداعمة لاعتمادها قبل التوريد والتنفيذ، ومنها: مراجعة تقرير التربة (الجسات) واعتماد نوع الأسمنت ودرجة عدوانية التربة، والتحقق الإنشائي للبلاطات اللاكمرية (الثقب حول الأعمدة) واعتماده من الاستشاري، ودراسة الأحمال الكهربائية وموازنة الأطوار وهبوط الجهد (≤ 3%) بترك احتياطي 20% في كل لوحة، وحساب أحمال التبريد على درجة حرارة تصميم خارجية لا تقل عن 46°م، وحسابات المضخات وأقطار المواسير ونظام الإطفاء (التدفق والضغط)، وحساب بطاريات الـ UPS، ودراسة شدة الإضاءة، وتصميم الجدار الساتر لأحمال الرياح من مكتب مرخص؛ وإجراء الاختبارات المعملية بمختبر معتمد وبحضور الاستشاري وتوثيقها بمحاضر: عينات الخرسانة، وكثافة دمك الردم وطبقات الأساس (≥ 95% بروكتر المعدل)، والعزل بالغمر، وضغط مواسير المياه والإطفاء، والتأريض، والتشغيل التجريبي لكل نظام؛ وتوريد شهادات المنشأ والمطابقة (SASO) وشهادات UL/FM لمواد أنظمة الحريق. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 430, null),
 ('LS-44', $q$مركز نموذج المسار الرابع$q$, $q$الحفر والردم وتسوية المناسيب$q$, $q$حساب كميات الحفر والقطع على مسؤولية المقاول من المخططات وتقرير التربة، وتنفيذها للأعماق والمناسيب المطلوبة للأعمال الخرسانية بالمعدات المناسبة، مع فصل الصالح من ناتج الحفر ونقل الباقي إلى مقلب البلدية المعتمد، ورش المياه لمنع الغبار؛ وتنفيذ الردم بالتربة المعتمدة حسب توصيات الاستشاري واختبارات التربة على طبقات من 20 إلى 40 سم مع الترطيب والدمك الميكانيكي حتى كثافة لا تقل عن 95% من بروكتر المعدل واختبار كل طبقة؛ وتسوية المناسيب النهائية للموقع بالميول المحققة للتصريف. ملاحظة: الظروف غير الظاهرة قبل الحفر (المياه الجوفية، التكهفات، أعمال تحسين التربة) تُعالج عند ظهورها بأمر مستقل وتكلفة يتحملها المالك وفق سعر السوق السائد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 440, '31'),
 ('LS-45', $q$مركز نموذج المسار الرابع$q$, $q$مكافحة النمل الأبيض$q$, $q$توريد ورش مبيد النمل الأبيض والحشرات المعتمد على الأسطح الأفقية والرأسية لكامل مسطح الحفر وأسفل المباني وحول محيطها في المستويات السفلية، بالتركيز والكميات الموصى بها من الشركة الصانعة، قبل صب الخرسانة العادية وقبل الردم، مع شهادة ضمان من الشركة المنفذة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 450, '31'),
 ('LS-46', $q$مركز نموذج المسار الرابع$q$, $q$الخرسانة الملامسة للتربة (الأساسات والميد والبلاطة الأرضية)$q$, $q$توريد وصب الخرسانة العادية تحت الأساسات بالسماكة الواردة في المخططات بمقاومة لا تقل عن 20 ميجا باسكال عند 28 يوماً فوق رقائق بولي إيثيلين 100 ميكرون مانعة للرطوبة؛ والخرسانة المسلحة الملامسة للتربة بمقاومة 40 ميجا باسكال للقواعد ورقاب الأعمدة والميدات، والبلاطة الأرضية المسلحة بسماكة 20 سم (أو حسب التصميم الإنشائي) فوق بولي إيثيلين 100 ميكرون، للمبنى الرئيسي ومبنى الميكانيكا؛ بأسمنت مقاوم للكبريتات (SRC – Type V) حسب تقرير التربة لطبيعة تربة الأحساء السبخية، ونسبة ماء/أسمنت لا تزيد عن 0.45، وغطاء خرساني 75 مم (SBC 304)؛ شاملاً القوالب وحديد التسليح والخلط والنقل والصب والفواصل الإنشائية ومانعات تسرب المياه (Waterstops)، والمعالجة بالترطيب 7 أيام على الأقل وتجنب الصب في ذروة الحرارة؛ وطلاء جميع أسطح الخرسانة الملامسة للتربة بطبقتين من البيتومين البارد (إيزوماكس أو ما يعادله) بعد تجهيز الأسطح. المصانع المعتمدة: العفالق، الكفاح، الناصر، الإبراهيم أو ما يعادلها. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 460, '03'),
 ('LS-47', $q$مركز نموذج المسار الرابع$q$, $q$الهيكل الخرساني العلوي$q$, $q$توريد وصب الخرسانة المسلحة بمقاومة 40 ميجا باسكال للأعمدة وكمرات الأسقف والسلالم، والبلاطات اللاكمرية (Flat Slab) لكامل أسقف المشروع وسقف بيت الدرج للمبنى الرئيسي ومبنى الميكانيكا، بأسمنت حسب المواصفات وتقرير التربة، شاملاً القوالب والدعامات وحديد التسليح والخلط والنقل والصب والمعالجة وفواصل التمدد والفتحات والجلسات والبروزات والديكورات الخرسانية الواردة في المخططات المعمارية؛ مع التحقق الإنشائي من الثقب (Punching Shear) حول الأعمدة واعتماده من الاستشاري قبل التنفيذ، واختبار العينات حسب المواصفات. المصانع المعتمدة: العفالق، الكفاح، الناصر، الإبراهيم أو ما يعادلها. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 470, '03'),
 ('LS-48', $q$مركز نموذج المسار الرابع$q$, $q$خزان المياه الأرضي$q$, $q$تصميم وتنفيذ خزان مياه أرضي من الخرسانة المسلحة بسعة تكفي احتياج المركز لمدة لا تقل عن 7 أيام مع احتياج ري المسطحات الخضراء (الحجم الاسترشادي 4×4×2.5 م، ويُحسب نهائياً من المقاول ويُعتمد)، شاملاً الحفر والخرسانة والعزل الخارجي، ورش طبقة بولي يوريا ساخنة سماكة 2 مم على الجدران والأرضية والسقف من الداخل، وغطاء محكم خاص، وفتحات تهوية، وسلم داخلي، ووصلات التغذية والسحب والفائض والتصريف، والتنظيف والتعقيم قبل التعبئة. وفي حال اعتماد سحب مضخة الحريق من خزان أرضي يُعاد حساب السعة لتشمل مخزون الحريق المطلوب حسب الكود أو يُنفذ خزان مستقل للحريق (يُنسق مع بند نظام الإطفاء). وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 480, '03'),
 ('LS-49', $q$مركز نموذج المسار الرابع$q$, $q$أعمال البلوك والجدران$q$, $q$حساب كميات البلوك من المخططات وتوريد وبناء جميع الجدران من البلوك الخرساني المفرغ أو المصمت أو المعزول بالمقاسات الواردة في المخططات (100 و150 و200 مم)، والجدران الخارجية مزدوجة (جدار خارجي + عازل حراري + جدار داخلي)، شاملاً المونة والأربطة وحديد التسليح الأفقي كل ثلاث مداميك والرأسي، والشمعات الخرسانية لربط جدران 15 سم في الممرات، والأعتاب، وزوايا ومسامير التثبيت؛ وجميع الجدران الداخلية بكامل الارتفاع حتى السقف الإنشائي مع إقفال جميع الفراغات بين الغرف بالمواد المعتمدة (وبمواد مقاومة للحريق حيث يلزم). المصانع المعتمدة: الإبراهيم، الناصر، أبتك، الكفاح أو ما يعادلها. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 490, '04'),
 ('LS-50', $q$مركز نموذج المسار الرابع$q$, $q$العزل الحراري للجدران والعزل المائي للمناطق الرطبة$q$, $q$توريد وتركيب ألواح عزل حراري من البوليسترين المنبثق عالي الكثافة (XPS) سماكة 50 مم عاشق ومعشوق لجميع الجدران الخارجية داخل الجدار المزدوج (الجفالي أو ما يعادله)؛ وتوريد وتنفيذ غشاء عازل للمياه من لفائف البيتومين طبقتين سماكة كل منهما 4 مم ملصوق بالكامل على الخرسانة الملساء للمناطق الرطبة ودورات المياه وغرف النظافة، شاملاً الارتفاع على الجدران وجميع الملحقات (درع الصحراء أو إيزوماكس أو ديرمابت أو ما يعادلها)، مع اختبار الغمر بالماء قبل التشطيب. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 500, '07'),
 ('LS-51', $q$مركز نموذج المسار الرابع$q$, $q$نظام عزل الأسطح$q$, $q$توريد وتنفيذ نظام عزل كامل للأسطح: طبقة خرسانة خفيفة لعمل الميول نحو المصارف، وعزل حراري بسماكة لا تقل عن 10 سم عالي الكثافة، وطبقة فصل من القماش غير المنسوج (140 غ/م²)، وطبقة بولي إيثيلين 100 ميكرون، وطبقتين من لفائف البيتومين سماكة 4 مم ملصوقة بالكامل على السطح الأفقي ومرتفعة على الجدران ومثبتة بشرائح الألمنيوم، والطبقة الحامية النهائية حسب المخططات، ومعالجة حول المصارف والفتحات وقواعد المعدات؛ واختبار الغمر بالماء لمدة لا تقل عن 72 ساعة بمحضر معتمد، وضمان للعزل لا يقل عن 10 سنوات. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 510, '07'),
 ('LS-52', $q$مركز نموذج المسار الرابع$q$, $q$الأقواس والعناصر المعمارية للواجهات$q$, $q$توريد وتنفيذ الأقواس الخارجية بالواجهات حسب المخططات المعمارية بكامل عناصرها: الحفر والقواعد الخرسانية المسلحة ورقاب الأعمدة والميدات، والهيكل المعدني (أعمدة وعوارض وأقواس) شاملاً القص والثني واللحام والصفائح والبراغي والأنكرات والحماية من الصدأ ببرايمر وإيبوكسي أو الجلفنة، والتغليف والتشكيل المعماري بالأسمنت بورد أو شبك البقلاوة مع اللياسة أو الأنظمة المناسبة للأعمال الخارجية المقاومة للرطوبة، والتشطيب النهائي المتوافق مع تشطيب المبنى (فايبر سمنت / كلادينج / GRC حسب التصميم) بجميع الحواف والزوايا وفواصل التمدد ومعالجات التقاء المواد؛ وتوريد وتركيب عناصر GRC الواردة في المخططات؛ شاملاً السقالات والرفع. يجوز للمقاول اقتراح منتج أو طريقة تنفيذ بديلة تُعتمد قبل التنفيذ، ولا يحق له المطالبة بأي بنود إضافية لإتمام هذا العمل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 520, '05'),
 ('LS-53', $q$مركز نموذج المسار الرابع$q$, $q$الدرابزين وممسحة المدخل والأعمال المعدنية$q$, $q$توريد وتركيب درابزين من الستانلس ستيل 304 مطفي قطر 40 مم للدرج الرئيسي ودرج الخدمة مثبت على الأرض بقوائمه وقواطعه الداخلية (Balustrades) حسب المخططات؛ وتوريد وتركيب ممسحة أرضية للمدخل الرئيسي من شبك الستانلس ستيل المضاد للصدأ في حفرة مجهزة بالمنسوب الصحيح (emco MARSCHALL Premium Large مع إدخال Care وشريط فرشاة 517 PSL Care B أو ما يعادلها)؛ وجميع الأعمال المعدنية الأخرى الواردة في المخططات (سلالم القطط، الأغطية، المظلات المعدنية الصغيرة) مدهونة بنظام مقاوم للصدأ. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 530, '05'),
 ('LS-54', $q$مركز نموذج المسار الرابع$q$, $q$الأبواب المعدنية والأقفال$q$, $q$توريد وتركيب جميع الأبواب المعدنية حسب جدول الأبواب: ضلفة 47 مم من صاج 1.6 مم وحلق 2.0 مم بتشطيب Flush، وحشوة صوف صخري مع مقويات للأبواب المقاومة للحريق وخلايا نحل لغيرها، مع الإكسسوارات والمفصلات والغالقات Grade 1 والدهان؛ وحماية Kick Plate بارتفاع لا يقل عن 90 سم (CS Group)؛ وعرض صافٍ لا يقل عن 95 سم للمفرد و180 سم للمزدوج وفق دليل الوصول الشامل. الأنواع: D1 مفرد مصمت (العيادات ودورات المياه الرئيسية)، D2 مفرد بنافذة رؤية (الكهرباء والاتصالات والمخازن والنظافة والتعقيم)، D3 مخرج طوارئ مقاوم للحريق (60/90 دقيقة حسب المخطط) يفتح للخارج بذراع خروج سريع Salto XS4 PBE900 مربوط بإنذار الحريق ومقفل دائماً إلا عند الإنذار مع إمكانية التخطي، D4 مزدوج بنوافذ رؤية بزجاج أمان لعيادة الطوارئ، D5 مزدوج لغرفة الميكانيكا؛ وأقفال إلكترونية Salto XS4 Original Wide بقفل Mortise حصراً لغرف الكهرباء والاتصالات والميكانيكا (مع مظلة تحمي القفل من الشمس)؛ وباب غرفة شركة الكهرباء وفق اشتراطاتها؛ ونظام مفاتيح ماستر مع صندوقي مفاتيح مرقمة بميداليات فينوليك. يُعتمد نوع كل قفل قبل التوريد. المصنّعون المعتمدون: HÖRMANN، الخضيمي، الدريس. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 540, '08'),
 ('LS-55', $q$مركز نموذج المسار الرابع$q$, $q$الباب الأوتوماتيكي للمدخل الرئيسي$q$, $q$توريد وتركيب باب انزلاقي أوتوماتيكي بدرفتين للمدخل الرئيسي: زجاج مزدوج مقسّى 8+8 مم بفراغ هوائي، وإطار ألمنيوم مدهون بودرة أو أنودايز باللون المعتمد، وعرض ممر صافٍ يسمح بعبور الكراسي المتحركة والنقالات؛ محرك Dorma EL 301 أو ما يعادله لخدمة الاستخدام الكثيف، وحساسات حركة على الوجهين وحساس أمان ضد الاصطدام، ومفتاح أوضاع (أوتوماتيك / مفتوح دائماً / مغلق / اتجاه واحد)؛ وربطه بإنذار الحريق ليفتح فتحاً كاملاً دائماً عند الإنذار (Fail-Safe)، وبطارية احتياطية تشغّله لمدة لا تقل عن ساعة؛ مع ضمان لا يقل عن سنتين على المحرك ونظام التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 550, '08'),
 ('LS-56', $q$مركز نموذج المسار الرابع$q$, $q$الواجهات الزجاجية والنوافذ والقواطع الزجاجية$q$, $q$توريد وتركيب جميع الواجهات الزجاجية والنوافذ الخارجية بنظام الجدار الساتر: زجاج مزدوج 6+12+6 مم (Guardian أو ما يعادله) بطبقة Low-E، مقسّى أو مصفّح للسلامة، بقيم أداء حراري (U-Value وSHGC) مطابقة لكود الطاقة السعودي (SBC 601)؛ ومقاطع ألمنيوم معزولة حرارياً (Thermal Break) مدهونة بودرة بوليستر بسماكة لا تقل عن 80 ميكرون، وقوائم مسلحة مصممة لأحمال الرياح من مكتب مرخص؛ وسيليكون إنشائي (Dow Corning 995 أو ما يعادله) وحشوات EPDM ونظام تصريف داخلي وفواصل تمدد؛ والنوافذ بنظام الأونينغ حيث ورد؛ وعيّنة كاملة (Mock-up) واختبارات نفاذية الهواء (ASTM E283) والمياه (ASTM E331) والحمل الإنشائي (ASTM E330)؛ والقياس الميداني ومخططات التصنيع على مسؤولية المقاول؛ والقاطع الزجاجي مع باب زجاجي للمكاتب الإدارية بزجاج مزدوج على مقاطع ألمنيوم؛ وضمان 10 سنوات ضد تسرب المياه والهواء و10 سنوات للسيليكون الإنشائي وسنتين للتركيب. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 560, '08'),
 ('LS-57', $q$مركز نموذج المسار الرابع$q$, $q$اللياسة$q$, $q$توريد وتنفيذ اللياسة الأسمنتية لجميع الحوائط الداخلية والخارجية والأسطح المبنية والخرسانية التي تتطلب لياسة، شاملاً الزوايا والخوص المعدنية لضبط الأحرف، والشبك الممدد عند التقاء البلوك بالخرسانة وحول التمديدات، والطرطشة والمعالجة بالرش، مع إقفال الفراغات بين الغرف بالمواد المعتمدة (المقاومة للحريق حيث يلزم)، وتسليم أسطح مستوية جاهزة للدهان أو التكسية. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 570, '09'),
 ('LS-58', $q$مركز نموذج المسار الرابع$q$, $q$الأرضيات الداخلية (الفينيل الطبي والموكيت والإيبوكسي)$q$, $q$توريد وتركيب أرضيات فينيل طبي متجانس من طبقة واحدة سماكة 2 مم معالج مصنعياً مقاوم للبكتيريا والكهرباء الساكنة والكيماويات والانزلاق (Gerflor Mipolam Infinity حصراً) لجميع المساحات الداخلية عدا الإدارة ودورات المياه وغرف الخدمات: على طبقة أسمنتية 7 سم وطبقة تسوية ذاتية ومادة لاصقة معتمدة، بلحام حراري للفواصل ووزرة فينيل مرفوعة 10 سم ملحومة مع الأرضية قطعة واحدة (Coving) وأغطية النهايات عند الأبواب، ومسار إرشادي لمسي (Tactile) من المادة نفسها من المدخل إلى كاونتر الاستقبال وفق دليل الوصول الشامل؛ وموكيت بلاطات 500×500×8 مم بولي بروبلين مقاوم للاشتعال للمكاتب الإدارية على طبقة تسوية وطبقة إسفنجية مع وزرة PVC بارتفاع 12 سم؛ ودهان إيبوكسي عديم الفواصل على طبقة تسوية أسمنتية مع زوايا مقعرة لغرف الخدمات (المستودع، الكهرباء، الاتصالات، الميكانيكا)؛ وتقديم عينات الألوان والأنواع للاعتماد قبل التوريد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 580, '09'),
 ('LS-59', $q$مركز نموذج المسار الرابع$q$, $q$التكسيات بالبورسلان والرخام والتيرازو$q$, $q$توريد وتركيب تكسيات البورسلان (EXA حصراً) لجدران وأرضيات دورات المياه وغرفة عامل النظافة وغرفة النفايات الطبية بكامل الارتفاع، شاملاً المواد اللاصقة والترويب والسيليكون والزوايا والميول نحو الصفايات؛ ورخام السلم الرئيسي وسلم الخدمة بالكامل (البسطات والقوائم والوزرات الجانبية) بسماكة 2 سم للقطع الرأسية و3 سم للأفقية بتشطيب غير لامع على الدرجات مع شرائح مانعة للانزلاق وملء الفواصل والتلميع؛ وبلاط التيرازو 250×250×25 مم للمواقع المحددة في المخططات على فرشة رمل ومونة 300 كجم/م³ مع فواصل تمدد لا تزيد عن 5×5 م وسقي بالأسمنت الأبيض؛ وتقديم عينات للاعتماد قبل التوريد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 590, '09'),
 ('LS-60', $q$مركز نموذج المسار الرابع$q$, $q$الأسقف المستعارة$q$, $q$توريد وتركيب الأسقف المعلقة من ألواح الجبس المقاوم للرطوبة والحريق سماكة 12 مم بمستوياتها وتفاصيلها لجميع المساحات الداخلية حسب المخططات (USG أو MADA حصراً)، شاملاً نظام التعليق والقطع المكملة والحواجز (Bulkheads) والدعائم الإضافية للارتفاعات، وفتحات الصيانة المخفية، والفتحات المنسقة مع الإنارة والتكييف والرشاشات والكواشف والسماعات، والمعجون والتجهيز للدهان، وفق مخططات الورشة المعتمدة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 600, '09'),
 ('LS-61', $q$مركز نموذج المسار الرابع$q$, $q$الدهانات الداخلية والخارجية$q$, $q$توريد وتنفيذ دهان الحوائط والأسقف الداخلية بالمستحلب الأكريليكي القابل للغسيل عالي الجودة (جوتن أو الجزيرة أو همبل) شاملاً تجهيز الأسطح والمعجون والصنفرة والأساس وطبقات التشطيب بالألوان المعتمدة؛ والدهانات الخارجية بالرشة مع الحبيبات وفق التصميم الخارجي المعتمد شاملاً معالجة الشروخ (Crack Filler) والطبقة الأساسية والإضافات المقاومة للعوامل الجوية؛ وتنفيذ عينة على الموقع للاعتماد قبل التنفيذ الكامل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 610, '09'),
 ('LS-62', $q$مركز نموذج المسار الرابع$q$, $q$حماية الحوائط والديكورات الداخلية$q$, $q$تنفيذ أعمال الديكورات حسب التصميم الداخلي المعتمد: تلبيس حماية الحوائط بألواح Acrovyn (CS Group) في الممرات وداخل العيادات والمكاتب وغرف الانتظار، وحماية الزوايا (Corner Guards – CS Group) لجميع الزوايا بارتفاع لا يقل عن 1.5 م، والديكورات الخشبية في العيادات ومنطقة الاستقبال من مواد مقاومة للخدوش والصدمات بلمسة خشبية؛ مع حساب الكميات على المقاول واعتماد الألوان، والتخطيط المبكر للتوريد لأن المواد مستوردة (يُطلب قبل التركيب بخمسة أشهر تقريباً). وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 620, '09'),
 ('LS-63', $q$مركز نموذج المسار الرابع$q$, $q$قواطع وإكسسوارات دورات المياه$q$, $q$توريد وتركيب قواطع واجهات المراحيض من ألواح HPL مضغوطة سماكة 19 مم بارتفاع 2.4 م بنظام بلا فراغات (Gap Free) مع الأبواب والأقفال والعلاقات والقواعد والتثبيت (Bobrick أو Fundermax)؛ وإكسسوارات Bobrick حصراً بالأعداد والمواقع حسب المخططات: مساند ذوي الإعاقة B-6806 وB-4998، ومجفف أيدي B-750 يعمل باللمس وبدونه، وحامل مناديل مدمج B-4388، وحاوية نفايات مدمجة B-43644، وحامل مناديل مع حاوية مدمج بجوار المغاسل B-3942، وعلاقات ملابس B-6827؛ وطاولة تغيير للأطفال مدمجة (Koala Kare KB310-SSRE أو ما يعادلها)؛ والمرايا فوق المغاسل؛ مع مراعاة اشتراطات دورات مياه ذوي الإعاقة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 630, '10'),
 ('LS-64', $q$مركز نموذج المسار الرابع$q$, $q$مستلزمات مكافحة العدوى الجدارية$q$, $q$توريد وتركيب مستلزمات مكافحة العدوى عند كل نقطة رعاية ومغسلة ومدخل عيادة حسب المخططات ومتطلبات IPC: حاويات النفايات الحادة الجدارية بحواملها، وموزعات الصابون الرغوي (Bobrick B-26627) والمعقم (Bobrick B-26628) بقواعدها الجدارية، وحوامل القفازات الثلاثية من الستانلس ستيل؛ مع اعتماد عينات قبل التوريد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 640, '10'),
 ('LS-65', $q$مركز نموذج المسار الرابع$q$, $q$اللوحات الخارجية والسارية$q$, $q$توريد وتركيب اللوحات المرورية والخارجية من الألمنيوم سماكة 1.5 مم بسطح عالي الانعكاس (أنواع IS-01 وIS-02 وRS-01 وWS-01 ولوحة نقطة التجمع) بأشكال وألوان مطابقة للائحة المرورية السعودية، على مواسير حاملة وقواعد خرسانية مقاومة للرياح؛ ولوحة المدخل المضيئة (نموذج S4) بعرض 4 م بشعار التجمع واسم المركز بإضاءة LED بحماية IP65 وتغذية مستقلة ويُعتمد تصميمها من التجمع؛ وسارية للعلم الوطني وعلم التجمع بارتفاع 6 م فوق الأرض ببكرة يدوية وقاعدة خرسانية وأعلام مطبوعة مقاومة للعوامل الجوية مع علمين احتياطيين، من شركة متخصصة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 650, '10'),
 ('LS-66', $q$مركز نموذج المسار الرابع$q$, $q$اللوحات الإرشادية الداخلية ولوحات السلامة$q$, $q$توريد وتركيب اللوحات الإرشادية الداخلية ولوحات العيادات والغرف ولوحات السلامة وخرائط الإخلاء (مادة الفوريكس أو حسب دليل الهوية) بالتصاميم والمحتوى الذي يحدده تجمع الأحساء الصحي؛ وهذا البند بمبلغ ثابت يحدده التجمع في الدعوة (لا يُنافَس عليه) ويُنفَّذ بتوجيه التجمع. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 660, '10'),
 ('LS-67', $q$مركز نموذج المسار الرابع$q$, $q$الكاونترات والنجارة الثابتة$q$, $q$توريد وتركيب الكاونترات حسب المخططات والصور المرفقة من خشب شيبورد صناعي مقاوم للرطوبة بحواف ABS وأسطح من الرخام الصناعي (Solid Surface)، بإكسسوارات ألمانية وأدراج بإغلاق هادئ (Soft Close)، ويُعتمد التصميم والعينات من مهندس المشروع: كاونتر الاستقبال بواجهة رخام صناعي مزدوج السماكة وجزء منخفض لا يزيد عن 80 سم لمستخدمي الكراسي المتحركة؛ كاونترات العيادات بحوض وخلاط إلكتروني يعمل باللمس وحاوية نفايات مدمجة مزدوجة (طبية/عادية)؛ كاونتر الاستراحة بحوض وخلاط إلكتروني ومايكرويف وغلاية ستانلس 10 لتر وثلاجة صغيرة بباب زجاجي أسفل الكاونتر وحاوية نفايات مدمجة؛ كاونتر عيادة الطوارئ بمغسلة وخلاط مختبرات؛ كاونتر سحب الدم والتطعيم والعلامات الحيوية؛ كاونتر الريموت كلينك؛ وكاونترات مغاسل دورات المياه من الرخام الصناعي بالمغاسل والخلاطات الإلكترونية والمرايا. الخلاطات: Ideal Standard أو Grohe حصراً. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 670, '12'),
 ('LS-68', $q$مركز نموذج المسار الرابع$q$, $q$الستائر ومكاتب الموظفين والنباتات الداخلية$q$, $q$توريد وتركيب ستائر طبية للمرضى بأقمشة مخصصة للاستخدام الطبي وسككها السقفية لكل عيادة (بطول 5 م وارتفاع 2.4 م) ولكبينتي العلامات الحيوية (بطول 2 م وارتفاع 2.4 م) مع طقمي أقمشة احتياطية لكل عيادة وكبينة؛ وستائر تعتيم (Blackout) يدوية لنوافذ العيادات الخارجية، وستائر شفافة (See-Through) يدوية لنوافذ المدخل والمكاتب، من مورد معتمد؛ وتوريد وتركيب مكاتب الموظفين بالمقاسات والمواد المحددة في المخططات؛ وأحواض نباتات داخلية صناعية عالية الجودة تحاكي الطبيعي ومقاومة للاشتعال بأحواض أسطوانية من الستانلس ستيل قطر 50 سم وارتفاع أشجار لا يقل عن 1.5 م، بعد اعتماد العينات. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 680, '12'),
 ('LS-69', $q$مركز نموذج المسار الرابع$q$, $q$المصعد$q$, $q$توريد وتركيب وتشغيل المصعد حسب المخططات من Schindler موديل 5000 حصراً، بجميع الإكسسوارات والمفاتيح والتشطيبات الداخلية والديكورات التي يختارها مهندس المشروع، شاملاً أعمال البئر والغرفة والتجهيزات الكهربائية وربطه بإنذار الحريق (الاستدعاء عند الحريق)، والاختبار والاعتماد من الجهات المختصة قبل التسليم، والصيانة الوقائية خلال فترة الضمان. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 690, '14'),
 ('LS-70', $q$مركز نموذج المسار الرابع$q$, $q$شبكة الإطفاء بالمياه والرشاشات$q$, $q$توريد وتركيب واختبار شبكة مواسير الإطفاء من الحديد الأسود الأملس غير الملحوم طولياً مدهونة باللون الأحمر بوصلات ومحابس جاهزة التركيب معتمدة UL، والمواسير المدفونة من HDPE معتمدة FM؛ والرشاشات التلقائية المعتمدة UL (Lifeco أو ما يعادلها)؛ ومجموعات محابس التحكم بالمناطق (Zone Control Valves) حسب NFPA 13: محبس OS&Y بمفتاح مراقبة، ومحبس عدم رجوع، وكاشف تدفق، ومحبس فحص وتصريف 1 بوصة بزجاجة رؤية، ومقياس ضغط معتمد، مع توصيل الصرف لأقرب نقطة؛ والوصلة السيامية للدفاع المدني (FDC) مقاس 4 بوصة بمخرجين 2.5 بوصة بمحبس عدم رجوع ومحبس بوابة معتمدة UL/FM في موقع ظاهر بلوحة تعريفية؛ شاملاً الدعامات والأعمال المدنية واختبار الشبكة عند مرة ونصف ضغط التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 700, '21'),
 ('LS-71', $q$مركز نموذج المسار الرابع$q$, $q$مضخات الحريق وخزان الحريق$q$, $q$توريد وتركيب وتشغيل واختبار مجموعة مضخات حريق متكاملة تعمل أوتوماتيكياً (NAFCO أو SFFECO) مكونة من مضخة كهربائية ومضخة ديزل ومضخة جوكي معتمدة UL/FM وفق NFPA 20، بلوحات تحكم آلي ويدوي وبطاريات شحن آلي لمضخة الديزل ومقاييس ومفاتيح الضغط وخزان وقود ومجرى عادم الديزل وتهوية غرفة المضخات، مع تقديم حسابات التدفق والضغط للاعتماد؛ وتوريد وتركيب خزان مياه الحريق من الفايبر جلاس فوق الأرض بسعة لا تقل عن 40 م³ بوصلاته ومحابسه ومضخة تدوير وفتحات تهوية وقاعدته، أو خزان خرساني أرضي مدمج مع خزان المياه إذا اعتُمدت مضخة مناسبة للسحب من الأسفل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 710, '21'),
 ('LS-72', $q$مركز نموذج المسار الرابع$q$, $q$كبائن الحريق والطفايات والإطفاء بالغاز النظيف$q$, $q$توريد وتركيب كبائن خراطيم الحريق الداخلية والخارجية (Fire Hose Reel) من الستانلس ستيل بأعلى سماكة وبباب منفصل (سفيكو أو ما يعادلها) شاملة طفاية 6 كجم متعددة الأغراض، بتوزيع يحقق مسافة وصول لا تزيد عن 30 م ويعتمده الدفاع المدني؛ وطفايات بودرة ABC سعة 6 كجم معتمدة FM موزعة حسب NFPA 10، وطفايات ثاني أكسيد الكربون 6 كجم بجوار اللوحات الكهربائية وغرف الخوادم، مدهونة إلكتروستاتيك من الخارج وPVC من الداخل بالحوامل وتعليمات عربي/إنجليزي، والطفايات على السطح بغطاء حماية من الشمس؛ ونظام إطفاء آلي بالغاز النظيف (FM200 أو Novec 1230) لغرفتي الكهرباء والاتصالات وفق NFPA 2001 بأسطوانته وفوهاته وشبكته ولوحة تحكمه وكواشفه وإنذاراته وأزرار التشغيل والإيقاف اليدوي، مع اختبارات القبول وشهادات الاعتماد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 720, '21'),
 ('LS-73', $q$مركز نموذج المسار الرابع$q$, $q$شبكات التغذية بالمياه والصرف وتصريف الأمطار$q$, $q$توريد وتركيب شبكة تغذية المياه الباردة والحارة من المواسير الحرارية (PPR) بالأقطار المحسوبة، والمواسير الرئيسية المدفونة من HDPE، بمحابس قفل نحاسية لكل منطقة وجهاز، مثبتة على الأسقف بنظام التعليق ومعزولة حيث يلزم؛ وشبكة الصرف والتهوية وتصريف الأمطار من UPVC Class 4 (مواسير الوطنية للبلاستيك وقطع السعودية للمسبوكات أو ما يعادلها) بجميع القطع والصفايات الأرضية وفتحات التنظيف وأغطية أعمدة التهوية وفوهات تصريف المطر وغرف التفتيش والجلي تراب، شاملاً السلفات والدفن والتثبيت والتوصيل بالشبكة العامة أو الخزان حسب المخططات؛ واختبار الضغط والتسرب لكل شبكة بمحضر معتمد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 730, '22'),
 ('LS-74', $q$مركز نموذج المسار الرابع$q$, $q$الأطقم الصحية$q$, $q$توريد وتركيب المراحيض الإفرنجية المعلقة بالسيفون المخفي (Geberit أو ما يعادله) مع شطاف لكل مرحاض، والمغاسل بخلاطات إلكترونية تعمل باللمس، والقطع المخصصة لذوي الإعاقة (ارتفاع مقعد المرحاض 45–48 سم، ومغسلة لا يزيد ارتفاعها عن 80 سم بخلوص للركبتين ومواسير معزولة أسفلها وخلاط بذراع طويل أو أوتوماتيكي) حسب دليل الوصول الشامل، وحوض تنظيف لغرفة النظافة (Janitor Sink) من الستانلس ستيل السميك بخلاطه وتصريفه؛ شاملاً المحابس والليات والإكسسوارات والأعمال المدنية والميكانيكية. الأطقم والخلاطات: Ideal Standard أو Grohe. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 740, '22'),
 ('LS-75', $q$مركز نموذج المسار الرابع$q$, $q$سخانات المياه ومضخات الضغط والري$q$, $q$توريد وتركيب وتشغيل سخانات المياه الكهربائية بسعة 80 جالون (A.O. Smith حصراً) على قواعد خرسانية مدهونة بالإيبوكسي، مع مضخة تدوير مياه ساخنة لكل سخان (Grundfos MAGNA1 حسب الحسابات) وتمديد خطوط التغذية والتدوير والراجع لكل مغسلة؛ ومجموعة مضخات ضغط (Booster) من Grundfos (CM/CME) من مضختين عاملة واحتياطية بإقلاع متبادل وتحكم بالسرعة وخزان ضغط إيطالي أو ألماني ولوحة تشغيل بمكونات ABB أو Schneider، بسعة استرشادية 3 لتر/ثانية ورفع 5 بار تُحسب نهائياً من المقاول؛ ومضخة ري المسطحات الخضراء (Grundfos CM/CME) بمنظم الضغط وفلتر الشوائب ولوحة التحكم؛ شاملاً القواعد والشاسيه والمحابس ومحابس عدم الرجوع والمواسير، مع تقديم حسابات السعات والأقطار للاعتماد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 750, '22'),
 ('LS-76', $q$مركز نموذج المسار الرابع$q$, $q$نظام الأكسجين الطبي$q$, $q$توريد وتركيب نظام الأكسجين الطبي حسب المخططات: مصدر التغذية (منظومة أسطوانات بمشعب تحويل آلي) وغرفته، ومواسير النحاس الطبي المنظفة لخدمة الأكسجين بوصلات ملحومة بالفضة تحت النيتروجين، وصمامات العزل في صناديق المناطق، ولوحات الإنذار، ومخارج الأكسجين في الطوارئ والمواقع المحددة؛ مع الاختبارات حسب HTM 02-01 أو NFPA 99 (الضغط، التسرب، النقاء، التقاطع، تحديد الهوية) وشهادة اعتماد قبل التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 760, '22'),
 ('LS-77', $q$مركز نموذج المسار الرابع$q$, $q$وحدات التكييف المركزية (Package) ومجاري الهواء$q$, $q$توريد وتركيب وتشغيل وحدتي تكييف من نوع Package (York DEH 360 حصراً) بالسعات ومعدلات الهواء والضغط الاستاتيكي حسب جدول المعدات وحساب أحمال تبريد على 46°م، بفلاتر عالية الكفاءة متوافقة مع ASHRAE 170 وفلاتر أولية ألمنيوم قابلة للغسيل ومصيدة رمل عند مأخذ الهواء الخارجي ومصيدة تكثف وعوازل اهتزاز وقواعد على السطح؛ ومجاري الهواء (تغذية وراجع وهواء نقي) من الصاج المجلفن عيار 24 بوصلات مرنة مقاومة للاشتعال، وعزل صوتي داخلي غير ليفي، وعزل فيبرجلاس داخلي 48 كجم/م³ سماكة 1 بوصة، وخارجي 64 كجم/م³ سماكة 1.5 بوصة مغلف بألمنيوم 0.8 مم على السطح؛ ومخمدات تحكم بالهواء Opposed Blade، ومخمدات حريق ودخان بتصنيف ساعتين معتمدة UL/FM بصناديق فحصها؛ ودفيوزرات تغذية بصناديق Plenum (طولية Linear Slot في الاستقبال ومربعة في غيرها) ودفيوزرات الراجع والهواء النقي؛ وفق ASHRAE وSMACNA وNFPA؛ واختبار المجاري بالدخان، وموازنة الهواء (TAB) من شركة متخصصة بتقرير معتمد، والتشغيل التجريبي. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 770, '23'),
 ('LS-78', $q$مركز نموذج المسار الرابع$q$, $q$وحدات التكييف المنفصلة والشفاطات والستائر الهوائية$q$, $q$توريد وتركيب وتشغيل وحدات تكييف منفصلة (LG أو Gree أو York) بكفاءة مطابقة لاشتراطات SASO وفريون صديق للبيئة ومواسير نحاس Mueller وعزل Armaflex لا يقل عن ¾ بوصة وغلاف حماية من الشمس للمواسير الخارجية، وصرف PVC 1 بوصة بكيعان 45° فقط ومضخة تكثف عند تعذر الميل، والوحدات الخارجية على قواعد خرسانية بعوازل اهتزاز مطاطية وقواطع خارجية IP65، واختبار التفريغ والتسريب، وضمان سنتين للوحدة و5 سنوات للكمبروسر (الفراغات الداخلية المحددة بسعة 2 طن وغرفة الميكانيكا بوحدتين 3 طن حسب المخططات)؛ ومراوح شفط سطحية Downblast Centrifugal (Greenheck أو Loren Cook) لدورات المياه وغرف النظافة والنفايات الطبية والميكانيكا بتشغيل مستمر على قواعد أصلية وعوازل اهتزاز وصمام عدم رجوع، ودكت مستقل لكل دورة مياه حتى السطح وأكمام حريق ومانع حريق عند اختراق البلاطات؛ وستارة هوائية تجارية عند باب المدخل الرئيسي بسرعة هواء 8–10 م/ث وضجيج لا يتجاوز 60 dB تعمل بحساس الباب وتتوقف عند إنذار الحريق. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 780, '23'),
 ('LS-79', $q$مركز نموذج المسار الرابع$q$, $q$اللوحات الكهربائية والكابلات الرئيسية$q$, $q$توريد وتركيب واختبار لوحة التوزيع الرئيسية (MDB) 400/230 فولت 60 هرتز وفق IEC 61439 بقاطع رئيسي MCCB بسعة 800 أمبير وقواطع فرعية حسب المخطط وأجهزة قياس متعددة الوظائف وحماية من زيادة التيار ونقص وزيادة الجهد والتسرب الأرضي؛ واللوحات الفرعية بقواطعها حسب جداول الأحمال: الإنارة والقوى (LP وDPP)، والأحمال الميكانيكية (DP-MECH)، والتكييف (DP-AC)، والأحمال الحرجة من الـ UPS (PP-UPS)، وإنارة الليل بكونتاكتور ومفتاح Manual-Off-Auto وخلية ضوئية أو مؤقت؛ من ABB أو Schneider حصراً بلوحات إرشادية لكل دائرة واحتياطي 20%؛ وكابلات الجهد المنخفض CU/XLPE/PVC 0.6/1 ك.ف من كابلات الرياض حصراً: من مصدر شركة الكهرباء إلى MDB ومنها إلى جميع اللوحات ووحدات التكييف والمصعد، وكابل مضخة الحريق مقاوم للحريق؛ بحوامل الكابلات والمواسير والدفن على الرمل وشرائط التحذير؛ والتنسيق مع الشركة السعودية للكهرباء لغرفة المحول واشتراطاتها؛ واختبارات مقاومة العزل والحقن والتتابع الطوري والتسرب الأرضي والفحص الحراري وشهادات FAT وSAT. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 790, '26'),
 ('LS-80', $q$مركز نموذج المسار الرابع$q$, $q$التمديدات والمخارج والإنارة$q$, $q$توريد وتركيب جميع مخارج القوى والمفاتيح والمقابس غاطسة في علب معدنية (Legrand BLANKO أو MK)، ومفاتيح العزل للسخانات والتكييف والمراوح، ووحدات رأس المريض حيث وردت، ونقاط الداتا؛ بأسلاك نحاسية من كابلات الرياض ومواسير EMT للظاهر وPVC للمخفي (Bahra أو Al-Rouf أو Riyadh House) وشبكة تأريض لكل نقطة؛ وجميع وحدات الإنارة الداخلية والخارجية والأعمدة وإنارة الطوارئ والمخارج: عمر تشغيلي لا يقل عن 50,000 ساعة بمحولات أوروبية، وبطارية طوارئ 3 ساعات للوحدات المحددة، وحساسات حركة في الفراغات والممرات، وحماية IP66 للخارجية وIP56 للمناطق الرطبة، ولوحات مخارج معتمدة UL، وربط إنارة الطوارئ بالـ UPS (PROlight وعلاماتها: LEDVANCE، PHILIPS، ULTRA LIGHT، Lunor، أو ما يعتمده مهندس المشروع)؛ مع دراسة شدة الإضاءة واختبارات الاستمرارية والعزل والتأريض والحساسات والتحويل للطوارئ. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 800, '26'),
 ('LS-81', $q$مركز نموذج المسار الرابع$q$, $q$نظام التأريض$q$, $q$توريد وتركيب واختبار نظام التأريض الكامل (ABB أو VERSE): آبار تأريض بقضبان نحاسية بطول 3 م وقطر 20 مم، وموصل نحاسي عارٍ 70 مم²، وماسكات ووصلات اختبار وقضبان تأريض، ولحام حراري (Exothermic) حيث يلزم؛ بمقاومة لا تتجاوز 4 أوم لنظام القوى، ونظام مستقل للتيار الخفيف لا تتجاوز مقاومته 2 أوم؛ وتأريض كمبروسرات التكييف والمعدات على السطح، وتأريض الأجهزة الطبية وفق IEC 60364-7-710؛ وإضافة آبار أو محسّن تربة عند الحاجة للوصول للقيم المطلوبة لطبيعة تربة الأحساء الملحية دون مطالبة إضافية؛ وقياس كل نظام على حدة بتقارير معتمدة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 810, '26'),
 ('LS-82', $q$مركز نموذج المسار الرابع$q$, $q$نظام الإمداد بالطاقة غير المنقطعة (UPS)$q$, $q$توريد وتركيب وتشغيل جهاز UPS صناعي من نوع On-Line Double Conversion بقدرة لا تقل عن 10 كيلو فولت أمبير (EATON أو ما يعادله) يغذي الأحمال الحرجة فقط (الأنظمة الطبية والخوادم وإنارة الطوارئ والمخارج الخاصة)، ببنك بطاريات يشغّل كامل الحمل ساعة واحدة على الأقل بحساب موثّق وفي مكان مكيّف، ولوحة مراقبة وشاشة، وتجاوز ثابت وتجاوز صيانة، وكابلات الدخول والخروج وقواطع العزل والتأريض؛ واختبارات الحمل الكامل وزمن البطارية والتحويل والتجاوز وشهادات المصنع والضمان. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 820, '26'),
 ('LS-83', $q$مركز نموذج المسار الرابع$q$, $q$الشبكة الهيكلية ونقاط الاتصال اللاسلكي$q$, $q$توريد وتركيب واختبار الشبكة الهيكلية للمركز وفق TIA/EIA-568: نقاط داتا Cat6A غاطسة (Legrand) وكابلات أفقية من الفئة نفسها، وكابلات ألياف ضوئية للربط الرأسي؛ ومفاتيح شبكية مُدارة تدعم PoE (Huawei) ولوحات توزيع Cat6A وأسلاك الوصل ومنظمات الكابلات وموزعات الألياف؛ وكبائن الشبكة بوحدات توزيع الكهرباء والمراوح والأبواب والتأريض والتنظيم الاحترافي للكابلات؛ ونقاط الوصول اللاسلكي (Access Points) في المواقع المحددة؛ ومسارات مستقلة عن كابلات القوى؛ واختبار كل نقطة بجهاز اعتماد الكابلات والألياف بجهاز OTDR، والترقيم المطابق لجدول الكابلات، وتسليم تقارير الاعتماد ومخططات As-Built وكتيبات التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 830, '27'),
 ('LS-84', $q$مركز نموذج المسار الرابع$q$, $q$السنترال (IP-PBX) وأجهزة الهاتف$q$, $q$توريد وتركيب وتهيئة نظام سنترال AVAYA IP Office 500 برخصة Essential Edition تدعم 50 تحويلة IP وبطاقات معالجة الصوت (VCM)، وأجهزة الهاتف العادية والمرئية بالأعداد المحددة بكابلات توصيل 3 م، والمفاتيح الشبكية اللازمة، والكبينة الأرضية بأربع مراوح ووحدة توزيع طاقة 6 منافذ ومنظمي كابلات رأسيين ورفّين؛ وبرمجة خطط الترقيم ومجموعات البحث والرسائل الصوتية والتحويل، وربط الخطوط الخارجية والشبكة الهيكلية؛ والاختبار والتوثيق وتدريب المستخدمين وفريق التقنية. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 840, '27'),
 ('LS-85', $q$مركز نموذج المسار الرابع$q$, $q$الإذاعة الداخلية وشاشات العرض$q$, $q$توريد وتركيب واختبار نظام الإذاعة الداخلية والإخلاء الصوتي (Bosch Praesideo/Plena أو DSPPA): الكبينة المركزية والمضخمات بقدرات تغطي جميع المناطق، ووحدة التحكم ومايكروفون النداء في الاستقبال، والسماعات السقفية ومفاتيح التحكم بالصوت، والتقسيم إلى مناطق نداء مستقلة، بكابلات مقاومة للحريق منخفضة الدخان (LSZH)، والربط بإنذار الحريق لرسائل الإخلاء؛ واختبار التغطية ومستوى الصوت لكل منطقة؛ وتوريد وتركيب شاشات العرض بالأحجام والمواقع المحددة بحواملها وتوصيلاتها. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 850, '27'),
 ('LS-86', $q$مركز نموذج المسار الرابع$q$, $q$نظام إنذار الحريق العنواني$q$, $q$توريد وتركيب وتشغيل واختبار نظام إنذار حريق عنواني (Gent من Honeywell) معتمد من الدفاع المدني: لوحة تحكم رئيسية بالحلقات والبطاريات الاحتياطية حسب الكود، وكواشف دخان وحرارة وكواشف دخان المجاري، ومحطات نداء يدوية، وأجهزة إنذار صوتي وضوئي، ووحدات مراقبة وتحكم وعزل الدائرة القصيرة؛ والربط مع التكييف (إيقاف الوحدات وإغلاق مخامد الحريق) والإذاعة (الإخلاء الصوتي) والباب الأوتوماتيكي وأذرع الطوارئ والمصعد والستارة الهوائية والإطفاء بالغاز؛ بكابلات مقاومة للحريق LSZH مفصولة عن القوى؛ والاختبار الشامل بحضور الإشراف والدفاع المدني والحصول على الاعتماد النهائي. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 860, '28'),
 ('LS-87', $q$مركز نموذج المسار الرابع$q$, $q$كاميرات المراقبة$q$, $q$توريد وتركيب واختبار نظام كاميرات مراقبة رقمية (Hikvision Ultra Series Smart IP): كاميرات 8 ميجابكسل ليلية/نهارية بالأشعة تحت الحمراء، قبة داخلية وBullet أو PTZ خارجية بحماية IP66، بتغذية PoE؛ وجهاز تسجيل شبكي (NVR) بأقراص مخصصة للمراقبة بسعة تكفي مدة الحفظ المطلوبة، وشاشات عرض في غرفة المراقبة، ومفاتيح PoE (Huawei)؛ بكابلات Cat6A من Belden والحوامل والمواسير؛ واختبار وضوح الصورة ليلاً ونهاراً وزوايا التغطية ومدة التخزين الفعلية. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 870, '28'),
 ('LS-88', $q$مركز نموذج المسار الرابع$q$, $q$نظام استدعاء التمريض$q$, $q$توريد وتركيب وتشغيل نظام استدعاء تمريض لاسلكي للمنشآت الصحية (SOLT أو ما يعادله): وحدة تحكم مركزية ومحطات تمريض بشاشات أو لوحات بيان تُظهر مصدر النداء صوتياً ومرئياً، ونقاط استدعاء بجانب الأسرّة وحبال سحب طوارئ في دورات المياه، ولمبات بيان خارج الغرف بألوان مميزة، وأجهزة إرسال واستقبال ومقويات تضمن تغطية كاملة بلا نقاط ميتة؛ واختبار كل نقطة وزمن الاستجابة والتغطية، وتدريب الكادر التمريضي. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 880, '28'),
 ('LS-89', $q$مركز نموذج المسار الرابع$q$, $q$البردورات والأرصفة والإنترلوك والحجر$q$, $q$توريد وتركيب بردورات خرسانية مسبقة الصب 50×30×15 سم مشطوفة على خرسانة 7 سم وطبقة أساس 20 سم حول الطرق والمواقف والأحواض (الرياض أو تميكس أو ما يعادلها)؛ وأرصفة الإنترلوك بسماكة 8 سم و10 سم تحت المواقف بأشكال ومقاسات حسب النموذج المعتمد على خرسانة عادية 10 سم مع فواصل التمدد والدك؛ والبلاط التحذيري والإرشادي للمكفوفين من موقف ذوي الإعاقة حتى المدخل وفق دليل الوصول الشامل؛ والحجر الطبيعي أو الجرانيت الفاخر لمنطقة المدخل الأمامية حسب المخططات؛ والمنحدرات والدرابزين الخارجي حيث ورد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 890, '32'),
 ('LS-90', $q$مركز نموذج المسار الرابع$q$, $q$السفلتة وتخطيط المواقف$q$, $q$توريد وتنفيذ أعمال السفلتة للموقع العام: طبقة أساس (Base Course) سماكة 30 سم مدموكة بكثافة لا تقل عن 95%، ورش MC1، وطبقة أسفلت أولى 7 سم، ورش RC2، وطبقة نهائية 5 سم بدرجة أسفلت مناسبة لحرارة الأحساء، بالمناسيب والميول (لا تقل عن 1%) المحققة لتصريف الأمطار؛ واختبار كثافة كل طبقة بمختبر معتمد؛ وتخطيط المواقف ومواقف ذوي الإعاقة بلوحاتها، ومصدات السيارات حسب النموذج المعتمد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 900, '32'),
 ('LS-91', $q$مركز نموذج المسار الرابع$q$, $q$الزراعة وشبكة الري$q$, $q$تنفيذ تصميم المسطحات الخضراء المعتمد من مكتب معتمد لدى الإدارة الهندسية؛ وتوريد وتركيب شبكة الري من HDPE أو UPVC ضغط 10 بار بالأقطار المحسوبة على عمق لا يقل عن 60 سم بالقطع الخاصة والردم بالرمل الناعم والاختبار، والمحابس الكهربائية (RainBird حصراً) وصناديقها وأسلاك التحكم ووحدة التحكم المركزية، والرشاشات والنقاطات؛ وتوريد وزراعة النباتات المتحملة للملوحة والحرارة والموفرة للمياه وفق جدول زراعي معتمد، والتربة الزراعية المختبرة الخالية من الأملاح والسماد وأحجار الديكور، بواسطة شركة متخصصة، مع الري والصيانة حتى الاستلام الابتدائي. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 910, '32')
