-- 0050: مجموعة «مركز نموذج المسار الرابع» في قائمة بنود المقطوعية (إنشاء مركز صحي كامل) مبنية على جدول كميات المراكز الصحية للمشاركة المجتمعية،
-- وتحديث أوصاف بنود عامة بما هو أدق (مرة واحدة فقط إن لم تُعدَّل من الإدارة)، وشعبة لكل بند مقطوعية، وجدول مقطوعية جاهز لمشروع مركز النعيم. قابل لإعادة التشغيل.
alter table public.ls_items add column if not exists div_code text;
create table if not exists public.seed_marks (key text primary key, at timestamptz not null default now());
alter table public.seed_marks enable row level security;

-- ---------- 1) بنود المجموعة
on conflict (code) do nothing;

-- ---------- 2) تحديث أوصاف البنود العامة (فقط إن كان الوصف ما زال نص البذرة الأصلي)
update public.ls_items set descr = $q$توريد وتركيب الأبواب (خشبية / معدنية / مقاومة للحريق حسب جدول الأبواب) بإطاراتها وأقفالها ومفصلاتها وغالقاتها Grade 1 وواقياتها (Kick Plate) ولوحاتها، بعرض صافٍ لا يقل عن 95 سم للمفرد و180 سم للمزدوج وفق دليل الوصول الشامل، والأبواب المقاومة للحريق ومخارج الطوارئ معتمدة بأذرع خروج سريع مربوطة بإنذار الحريق، وأقفال إلكترونية لغرف الكهرباء والاتصالات والميكانيكا حيث وردت، ونظام مفاتيح ماستر مرقم؛ والشبابيك وملحقاتها؛ مع ضبط التشغيل والتسليم.$q$, updated_at = now() where code = 'LS-10' and descr = $q$توريد وتركيب الأبواب (خشبية / معدنية / مقاومة للحريق حسب المخططات) بإطاراتها وأقفالها ومفصلاتها وغالقاتها وواقياتها ولوحاتها، والشبابيك وملحقاتها، مع ضبط التشغيل والتسليم.$q$;
update public.ls_items set descr = $q$توريد وتركيب الواجهات الزجاجية والأبواب الأوتوماتيكية المنزلقة: زجاج مزدوج مقسّى أو مصفّح بأداء حراري مطابق لكود الطاقة (SBC 601)، ومقاطع ألمنيوم معزولة حرارياً مدهونة بودرة، وسيليكون إنشائي وحشوات EPDM؛ وللأبواب الأوتوماتيكية محرك للاستخدام الكثيف وحساسات على الوجهين وحساس أمان ومفتاح أوضاع، وربط بإنذار الحريق للفتح الكامل عند الإنذار، وبطارية احتياطية لا تقل عن ساعة؛ مع العينات والاختبار والبرمجة والضمان.$q$, updated_at = now() where code = 'LS-11' and descr = $q$توريد وتركيب الواجهات الزجاجية والأبواب الأوتوماتيكية المنزلقة (زجاج مقسّى / مزدوج حسب المخططات) بأنظمة الألمنيوم والحساسات والمحركات وبطاريات الطوارئ والأقفال، مع البرمجة والاختبار والضمان.$q$;
update public.ls_items set descr = $q$توريد وتنفيذ أعمال العزل المائي للأسطح ودورات المياه والمناطق الرطبة (لفائف بيتومين طبقتين 4 مم أو نظام معتمد مكافئ) والعزل الحراري للأسطح والجدران حسب المواصفات، شاملة تجهيز الأسطح وطبقات الميول والفصل والطبقات الحامية والارتفاع على الجدران وتثبيت الحواف بشرائح الألمنيوم، واختبار الغمر بالماء لمدة لا تقل عن 72 ساعة بمحضر معتمد.$q$, updated_at = now() where code = 'LS-13' and descr = $q$توريد وتنفيذ أعمال العزل المائي للأسطح ودورات المياه والمناطق الرطبة، والعزل الحراري حسب المواصفات، شاملة تجهيز الأسطح والطبقات الحامية والاختبار بالماء.$q$;
update public.ls_items set descr = $q$توريد وتركيب وحدات الإنارة الجديدة (LED) الداخلية بأنواعها بعمر تشغيلي لا يقل عن 50,000 ساعة ومحولات أوروبية، ووحدات إنارة الطوارئ ببطارية لا تقل عن 3 ساعات ولوحات المخارج المعتمدة، مع حساسات الحركة حيث يلزم، وحماية IP56 للمناطق الرطبة، وإزالة الوحدات القديمة، حسب المخططات ودراسة شدة الإضاءة المعتمدة، واختبار التحويل للطوارئ.$q$, updated_at = now() where code = 'LS-18' and descr = $q$توريد وتركيب وحدات الإنارة الجديدة (LED) الداخلية بأنواعها ووحدات إنارة الطوارئ ولوحات المخارج، مع التحكم والحساسات حيث يلزم، وإزالة الوحدات القديمة، حسب المخططات ومستويات الإضاءة المطلوبة.$q$;
update public.ls_items set descr = $q$توريد وتركيب لوحات التوزيع الفرعية وفق IEC 61439 (ABB أو Schneider) والقواطع والكيابل الرئيسية (كابلات الرياض) من المصدر إلى اللوحات، وتعديل اللوحات القائمة، بناءً على دراسة أحمال وموازنة أطوار وهبوط جهد لا يتجاوز 3% واحتياطي 20%، مع الترقيم واللوحات الإرشادية واختبارات العزل والفحص الحراري والتسليم حسب المخططات.$q$, updated_at = now() where code = 'LS-19' and descr = $q$توريد وتركيب لوحات التوزيع الفرعية والقواطع والكيابل الرئيسية من المصدر إلى اللوحات، وتعديل اللوحات القائمة، مع الترقيم والاختبار والتسليم حسب المخططات.$q$;
update public.ls_items set descr = $q$توريد وتمديد وتركيب أنظمة التيار الخفيف: شبكة البيانات Cat6A والهاتف، ونقاط الاتصال اللاسلكي، ونداء التمريض، وكاميرات المراقبة IP، ونظام الصوت والإذاعة، والتحكم بالدخول، شاملة المخارج والكيابل والمسارات المستقلة عن القوى والكبائن واللوحات والتأريض المستقل، واختبار اعتماد كل نقطة والترقيم والتسليم بمخططات As-Built حسب المخططات.$q$, updated_at = now() where code = 'LS-20' and descr = $q$توريد وتمديد وتركيب أنظمة التيار الخفيف: شبكة البيانات والهاتف، نداء الممرضات، كاميرات المراقبة، نظام الصوت والإذاعة، التحكم بالدخول، شاملة المخارج والكيابل واللوحات والاختبار والتسليم حسب المخططات.$q$;
update public.ls_items set descr = $q$توريد وتركيب أو تعديل وتوسعة نظام إنذار الحريق العنواني في النطاق: الكواشف ومحطات النداء اليدوية وأجهزة الإنذار الصوتي والضوئي ووحدات المراقبة والتحكم وعزل الدائرة القصيرة، بكابلات مقاومة للحريق LSZH، والربط باللوحة الرئيسية وبالتكييف والأبواب والأنظمة الأخرى، مع البرمجة والاختبار الشامل والتسليم والاعتماد من الدفاع المدني.$q$, updated_at = now() where code = 'LS-21' and descr = $q$تعديل وتوسعة نظام إنذار الحريق في النطاق: الكواشف والجرس والأضواء ونقاط الإنذار اليدوية والكيابل والربط باللوحة الرئيسية، مع البرمجة والاختبار والتسليم للجهات المختصة.$q$;
update public.ls_items set descr = $q$إزالة واستبدال أو تنفيذ تمديدات التغذية بالمياه الحارة والباردة (مواسير حرارية PPR، والمدفونة HDPE) والصرف والتهوية (UPVC Class 4)، والأطقم الصحية والخلاطات والصمامات والملحقات، حسب المخططات، شاملة الاختبار بالضغط والتوصيل بالشبكات القائمة.$q$, updated_at = now() where code = 'LS-23' and descr = $q$إزالة واستبدال تمديدات التغذية بالمياه (حار / بارد) والصرف والتهوية، والأطقم الصحية والخلاطات والصمامات والملحقات، حسب المخططات، شاملة الاختبار بالضغط والتوصيل بالشبكات القائمة.$q$;
update public.ls_items set descr = $q$توريد وتركيب / استبدال سخانات المياه ومضخات التدوير والضغط (مجموعات عاملة واحتياطية بتحكم في السرعة وخزان ضغط) وخزانات المياه وملحقاتها ولوحات التحكم حسب المخططات وحسابات السعات المعتمدة، شاملة القواعد والتوصيلات والعزل والاختبار والتشغيل.$q$, updated_at = now() where code = 'LS-26' and descr = $q$توريد وتركيب / استبدال سخانات المياه والمضخات وخزانات المياه وملحقاتها ولوحات التحكم حسب المخططات، شاملة التوصيلات والعزل والاختبار والتشغيل.$q$;
update public.ls_items set descr = $q$تنفيذ أعمال التشجير والمسطحات الخضراء وشبكة الري الآلي (مواسير HDPE أو UPVC ضغط 10 بار، ومحابس كهربائية، ووحدة تحكم مركزية، ورشاشات ونقاطات) في نطاق العمل حسب المخططات، بنباتات متحملة للملوحة والحرارة وتربة زراعية مختبرة خالية من الأملاح، شاملة الصيانة والري حتى الاستلام الابتدائي.$q$, updated_at = now() where code = 'LS-29' and descr = $q$تنفيذ أعمال التشجير والمسطحات الخضراء وشبكة الري الآلي والتحكم في نطاق العمل حسب المخططات، شاملة التربة الزراعية والصيانة خلال فترة الضمان.$q$;
update public.ls_items set descr = $q$توريد وتركيب أعمدة ووحدات الإنارة الخارجية (LED) بحماية لا تقل عن IP66 وإنارة الواجهات والمداخل والتمديدات والتحكم بالخلية الضوئية أو المؤقت حسب المخططات، مع إزالة القديم والاختبار.$q$, updated_at = now() where code = 'LS-30' and descr = $q$توريد وتركيب أعمدة ووحدات الإنارة الخارجية (LED) وإنارة الواجهات والمداخل والتمديدات والتحكم الزمني حسب المخططات، مع إزالة القديم والاختبار.$q$;
update public.ls_items set descr = $q$إجراء اختبارات التشغيل والموازنة لجميع الأنظمة (كهرباء، تكييف، صحية، إطفاء، تيار خفيف) بحضور ممثل الإدارة والاستشاري، ومنها: موازنة الهواء (TAB) من شركة متخصصة، واختبار الضغط للمواسير، واختبارات العزل والتأريض، والتشغيل التجريبي لكل نظام والاختبار الشامل المتكامل لأنظمة الحريق، ومعالجة الملاحظات، وتقديم تقارير الاختبار المعتمدة والحصول على اعتمادات الجهات المختصة (الدفاع المدني وغيرها).$q$, updated_at = now() where code = 'LS-31' and descr = $q$إجراء اختبارات التشغيل والموازنة لجميع الأنظمة (كهرباء، تكييف، صحية، إطفاء، تيار خفيف) بحضور ممثل الإدارة، ومعالجة الملاحظات، وتقديم تقارير الاختبار المعتمدة.$q$;
update public.ls_items set descr = $q$التنظيف النهائي الشامل وإزالة المخلفات وإصلاح ما تضرر، وتسليم المخططات كما نُفِّذ (As-built) وكتيبات التشغيل والصيانة (O&M) وشهادات الضمان: ضمان عام لا يقل عن سنة من الاستلام الابتدائي وضمانات المصنّعين للأجهزة حسب مددها، وقطع الغيار الاحتياطية للأنظمة الحرجة وفق توصيات الشركات الصانعة، وتدريب فريق التشغيل على الأنظمة الكهربائية والميكانيكية وأنظمة السلامة قبل الاستلام.$q$, updated_at = now() where code = 'LS-32' and descr = $q$التنظيف النهائي الشامل وإزالة المخلفات وإصلاح ما تضرر من المناطق المجاورة، وتسليم المخططات كما نُفِّذ (As-built) وشهادات الضمان والكتيبات وقطع الغيار الاحتياطية، وتدريب فريق التشغيل.$q$;
update public.ls_items set descr = $q$الالتزام بمتطلبات السلامة والصحة المهنية (المجلس السعودي للسلامة) ومعدات الوقاية الشخصية وخطة الطوارئ، ومكافحة العدوى عند العمل داخل منشأة عاملة أو بجوارها، واستخراج التصاريح اللازمة، والتنسيق مع الأقسام التشغيلية والجهات المختصة طوال مدة التنفيذ، وتقديم خطة العمل والجدول الزمني والتقارير الدورية.$q$, updated_at = now() where code = 'LS-33' and descr = $q$الالتزام بمتطلبات السلامة والصحة المهنية ومكافحة العدوى، واستخراج التصاريح اللازمة، والتنسيق مع الأقسام التشغيلية والجهات المختصة طوال مدة التنفيذ، وتقديم خطة العمل والجدول الزمني والتقارير الدورية.$q$;

-- ---------- 3) النطاق الجاهز

-- ---------- 4) جدول مقطوعية مركز النعيم (يُنشأ مرة واحدة؛ إن حُذف لا يُعاد)
do $$ declare p uuid; b uuid; begin
  if exists (select 1 from public.seed_marks where key = 'boq_naeem_track4') then return; end if;
  select id into p from public.projects where name like '%النعيم%' order by created_at limit 1;
  if p is null then return; end if;
    values (p, 'مقطوعية — نموذج المسار الرابع', 'tender', 'lumpsum', true, 5, 15, 1, $q$1. الأسعار مقطوعية شاملة جميع أعمال التوريد والتنفيذ والمواد والعمالة والمعدات والنقل والاختبار والتشغيل والتسليم والضمان والمصاريف العامة والأرباح.
2. المخططات والمواصفات وهذا الجدول وثائق مكملة لبعضها؛ وعند التعارض يُرجع للمهندس المشرف قبل التنفيذ ويُعتمد الأعلى مواصفةً. زيارة الموقع ومعاينة المناسيب والأبعاد إلزامية قبل التسعير.
3. على المقاول دراسة المخططات وحساب جميع الكميات على مسؤوليته والاستفسار قبل التسعير؛ ولا تُقبل أي مطالبة بفروقات كميات أو أسعار أو أعمال ناتجة عن قصور الدراسة، ويُنفَّذ التصميم الخارجي والديكورات والبروزات كاملة كما في المخططات.
4. أي أعمال لازمة لإنجاز المبنى كاملاً جاهزاً للتشغيل تُعدّ مشمولة في المقطوعية ولو لم تُذكر صراحةً.
5. على المقاول إعداد الرسومات التنفيذية (Shop Drawings) لجميع الأعمال والتصاميم التكميلية حيث لا تكفي المخططات، بمهندسين مختصين وعلى حسابه، واعتمادها قبل التنفيذ، وتسليم مخططات كما نُفِّذ؛ وكل ذلك مشمول في السعر.
6. الأكواد المرجعية: كود البناء السعودي بأبوابه (SBC 201/301/401/501/601/701/801) وNFPA وASHRAE وIEC، واشتراطات وزارة الصحة ومكافحة العدوى (IPC) ودليل الوصول الشامل.
7. مناخ الأحساء وتربتها: أحمال التبريد على درجة تصميم خارجية لا تقل عن 46°م، وعزل جميع المواسير والدكت الخارجية ضد الشمس، ومواد مقاومة للأملاح والرطوبة، وأسمنت مقاوم للكبريتات وعزل أساسات مناسب للتربة السبخية حسب تقرير التربة.
8. تُورَّد المواد جديدة أصلية من المصنّعين المعتمدين المذكورين في كل بند أو ما يعادلها بعد اعتماد خطي من الاستشاري، عدا ما وُصف بـ«حصراً». تُقدَّم العينات والبيانات الفنية ومخططات التصنيع قبل التوريد، وتُرفض أي مادة غير مطابقة وتُستبدل على نفقة المقاول دون تمديد للمدة.
9. المواد المستوردة طويلة التوريد (الديكورات وحماية الحوائط، المصعد، الأنظمة الخاصة) تُطلب مبكراً بما يتوافق مع الجدول الزمني، ولا يُعدّ تأخر الشحن مبرراً للتمديد.
10. بند اللوحات الإرشادية الداخلية ولوحات السلامة بمبلغ ثابت يحدده التجمع ولا يُنافَس عليه.
11. الظروف غير الظاهرة قبل الحفر (المياه الجوفية، التكهفات، تحسين التربة) تُعالج بأمر مستقل على حساب المالك وفق سعر السوق.$q$) returning id into b;
    select b, 'free', i.title, i.descr, i.unit, 1, i.div_code, o.n::int from unnest(array['LS-41','LS-42','LS-43','LS-40','LS-44','LS-45','LS-46','LS-47','LS-48','LS-49','LS-50','LS-51','LS-52','LS-53','LS-54','LS-55','LS-56','LS-57','LS-58','LS-59','LS-60','LS-61','LS-62','LS-63','LS-64','LS-65','LS-66','LS-67','LS-68','LS-69','LS-70','LS-71','LS-72','LS-73','LS-74','LS-75','LS-76','LS-77','LS-78','LS-79','LS-80','LS-81','LS-82','LS-83','LS-84','LS-85','LS-86','LS-87','LS-88','LS-89','LS-90','LS-91','LS-31','LS-32','LS-33']::text[]) with ordinality as o(code, n) join public.ls_items i on i.code = o.code;
end $$;
